import java.util.Scanner;

class NumberManipulation {

    int fibonacciNthTerm(int n) {

        int fib1 = 0;
        int fib2 = 1;

        if (n == 1) {
            return fib1;
        }

        if (n == 2) {
            return fib2;
        }

        int term = 0;

        for (int i = 3; i <= n; i++) {
            term = fib1 + fib2;

            fib1 = fib2;
            fib2 = term;
        }

        return fib2;
    }

    void fibonacci(int n) {

        int fib1 = 0;
        int fib2 = 1;

        if (n == 1) {
            System.out.println(fib1);
        }
        else if (n == 2) {
            System.out.println(fib1 + " " + fib2);
        }
        else {
            System.out.print(fib1 + " " + fib2);

            for (int i = 3; i <= n; i++) {

                int term = fib1 + fib2;

                System.out.print(" " + term);

                fib1 = fib2;
                fib2 = term;
            }

            System.out.println();
        }
    }
}

public class Main {

    public static void main(String[] args) {

        Scanner scan = new Scanner(System.in);

        NumberManipulation manipulation = new NumberManipulation();

        System.out.print("Enter n for nth Fibonacci term: ");
        int n = scan.nextInt();

        int result = manipulation.fibonacciNthTerm(n);

        System.out.println("Nth Fibonacci term = " + result);

        System.out.print("Enter number of Fibonacci terms to print: ");
        n = scan.nextInt();

        System.out.print("Fibonacci series: ");
        manipulation.fibonacci(n);

        scan.close();
    }
}

